module Moderate
  class PreviewsController < BaseController
    before_action :set_quiz

    def show
      @questions = @quiz.active_questions.includes(:options).to_a
      @total = @questions.size

      if @total == 0
        # No active questions: render empty state
        @index = 0
        @question = nil
        @picked_option_id = nil
        return
      end

      @index = params[:q].to_i
      @index = 0 if @index < 0
      @index = @total - 1 if @index >= @total

      @question = @questions[@index]
      answers = preview_answers_for_quiz
      @picked_option_id = answers[@question.id.to_s]
      if @picked_option_id
        picked = @question.options.find { |o| o.id.to_s == @picked_option_id.to_s }
        @picked_correct = picked ? picked.correct? : false
      else
        @picked_correct = nil
      end
    end

    def answer
      @questions = @quiz.active_questions.includes(:options).to_a
      @total = @questions.size
      idx = params[:q].to_i
      idx = 0 if idx < 0
      idx = @total - 1 if @total > 0 && idx >= @total
      question = @questions[idx]

      unless question
        redirect_to preview_moderate_quiz_path(@quiz) and return
      end

      option_id = params[:option_id].to_s
      # Validate option belongs to question
      valid_ids = question.options.map { |o| o.id.to_s }
      if valid_ids.include?(option_id)
        answers = preview_answers_for_quiz
        answers[question.id.to_s] = option_id
        save_preview_answers_for_quiz(answers)
      end

      redirect_to preview_moderate_quiz_path(@quiz, q: idx)
    end

    def result
      @questions = @quiz.active_questions.includes(:options).to_a
      @total = @questions.size
      answers = preview_answers_for_quiz
      @score = 0
      @questions.each do |q|
        picked_id = answers[q.id.to_s]
        next unless picked_id
        opt = q.options.find { |o| o.id.to_s == picked_id.to_s }
        @score += 1 if opt && opt.correct?
      end
    end

    def reset
      all = session[:preview_answers] || {}
      # session may have string keys; ensure hash
      if all.is_a?(Hash)
        all = all.dup
        all.delete(@quiz.id.to_s)
        all.delete(@quiz.id)
        session[:preview_answers] = all
      else
        session[:preview_answers] = {}
      end
      redirect_to preview_moderate_quiz_path(@quiz, q: 0)
    end

    private

    def set_quiz
      @quiz = Quiz.find(params[:id] || params[:quiz_id])
    end

    def preview_answers_for_quiz
      all = session[:preview_answers]
      all = {} unless all.is_a?(Hash)
      # Normalize keys to strings
      quiz_key = @quiz.id.to_s
      val = all[quiz_key] || all[@quiz.id] || {}
      val = {} unless val.is_a?(Hash)
      # Return dup with string keys
      result = {}
      val.each { |k, v| result[k.to_s] = v.to_s }
      result
    end

    def save_preview_answers_for_quiz(answers_hash)
      all = session[:preview_answers]
      all = {} unless all.is_a?(Hash)
      all = all.dup
      # stringify
      new_inner = {}
      answers_hash.each { |k, v| new_inner[k.to_s] = v.to_s }
      all[@quiz.id.to_s] = new_inner
      session[:preview_answers] = all
    end
  end
end
